rule.template:
-- No BROKER SCHEMA: file is at project root level (omit for root-level files)
BROKER SCHEMA gen   -- include only when file is inside a subfolder

-- Namespace aliases
DECLARE ns1 NAMESPACE 'http://services.example.com/';

-- EXTERNAL variables: correspond to subflow UDP properties (eStructuralFeatures)
-- Configurable per-environment via properties files
DECLARE BackendUrl   EXTERNAL CHARACTER 'http://default.example.com/api';
DECLARE ApiKey       EXTERNAL CHARACTER '';

-- SHARED variables: in-memory state shared across all message flow threads
DECLARE CacheData          SHARED ROW;
DECLARE LastCacheRefreshTs SHARED TIMESTAMP NULL;

CREATE COMPUTE MODULE MyFlow_MyNode
    CREATE FUNCTION Main() RETURNS BOOLEAN
    BEGIN
        -- main logic
        RETURN TRUE;
    END;

    CREATE PROCEDURE CopyMessageHeaders() BEGIN
        DECLARE I INTEGER 1;
        DECLARE J INTEGER;
        SET J = CARDINALITY(InputRoot.*[]);
        WHILE I < J DO
            SET OutputRoot.*[I] = InputRoot.*[I];
            SET I = I + 1;
        END WHILE;
    END;

    CREATE PROCEDURE CopyEntireMessage() BEGIN
        SET OutputRoot = InputRoot;
    END;
END MODULE;

rule.correct_example:
-- Requires parseQueryString="true" on the HTTP Input node in the .msgflow
SET location = COALESCE(InputLocalEnvironment.HTTP.Input.QueryString.location, '');
SET units    = COALESCE(InputLocalEnvironment.HTTP.Input.QueryString.units, 'metric');

rule.template:
-- Build the complete backend URL including query parameters
SET backendUrl = BackendBaseUrl || '?q=' || location || '&key=' || ApiKey;

-- Set on OutputLocalEnvironment — the HTTP Request node picks this up at runtime
SET OutputLocalEnvironment = InputLocalEnvironment;
SET OutputLocalEnvironment.Destination.HTTP.RequestURL = backendUrl;
SET OutputLocalEnvironment.Destination.HTTP.RequestLine.Method = 'GET';

CALL CopyMessageHeaders();
RETURN TRUE;

CREATE COMPUTE MODULE MyFlow_ErrorHandler
    CREATE FUNCTION Main() RETURNS BOOLEAN
    BEGIN
        DECLARE backendStatus INTEGER;

        SET OutputLocalEnvironment = InputLocalEnvironment;

        -- Read backend status from InputRoot (InputLocalEnvironment is empty on error terminal)
        SET backendStatus = CAST(
            InputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Code" AS INTEGER
        );

        IF backendStatus IS NOT NULL AND backendStatus > 0 THEN
            -- Pass the backend's response (status + body) straight through to the client
            CREATE NEXTSIBLING OF OutputRoot.Properties DOMAIN 'HTTPResponseHeader';
            SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Code" = backendStatus;
            SET OutputRoot.BLOB.BLOB = InputRoot.BLOB.BLOB;
        ELSE
            -- Flow-level failure (connection error, DNS failure, etc.)
            CREATE NEXTSIBLING OF OutputRoot.Properties DOMAIN 'HTTPResponseHeader';
            SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Line" = 'HTTP/1.1 500 Internal Server Error';
            SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Code" = 500;
            SET OutputRoot.JSON.Data.error.code = 'BACKEND_ERROR';
            SET OutputRoot.JSON.Data.error.message = COALESCE(
                InputExceptionList.RecoverableException[1].Insert[1].Text,
                'An unexpected error occurred calling the backend service.'
            );
        END IF;

        RETURN TRUE;
    END;

    CREATE PROCEDURE CopyMessageHeaders() BEGIN
        DECLARE I INTEGER 1;
        DECLARE J INTEGER;
        SET J = CARDINALITY(InputRoot.*[]);
        WHILE I < J DO
            SET OutputRoot.*[I] = InputRoot.*[I];
            SET I = I + 1;
        END WHILE;
    END;

    CREATE PROCEDURE CopyEntireMessage() BEGIN
        SET OutputRoot = InputRoot;
    END;
END MODULE;

-- Return HTTP 400 Bad Request with a JSON error body
CREATE NEXTSIBLING OF OutputRoot.Properties DOMAIN 'HTTPResponseHeader';
SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Line" = 'HTTP/1.1 400 Bad Request';
SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Code" = 400;
SET OutputRoot.JSON.Data.error.code = 'MISSING_PARAMETER';
SET OutputRoot.JSON.Data.error.message = 'Required parameter "location" is missing.';

-- Return HTTP 500 Internal Server Error with a JSON error body
CREATE NEXTSIBLING OF OutputRoot.Properties DOMAIN 'HTTPResponseHeader';
SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Line" = 'HTTP/1.1 500 Internal Server Error';
SET OutputRoot.HTTPResponseHeader."X-Original-HTTP-Status-Code" = 500;
SET OutputRoot.JSON.Data.error.code = 'SERVER_ERROR';
SET OutputRoot.JSON.Data.error.message = 'An unexpected error occurred.';

patterns.pattern:
DECLARE r_item REFERENCE TO InputRoot.SOAP.Body.ns:Response.Item[1];
WHILE LASTMOVE(r_item) DO
    SET outref.field = r_item.value;
    CREATE NEXTSIBLING OF outref AS outref REPEAT;
    MOVE r_item NEXTSIBLING;
END WHILE;

-- File-scope (outside modules)
DECLARE CacheData          SHARED ROW;
DECLARE LastCacheRefreshTs SHARED TIMESTAMP NULL;

-- Cache expiry check (TTL = 8 hours = 28800 seconds)
IF (LastCacheRefreshTs IS NULL OR
    CAST((CURRENT_TIMESTAMP - LastCacheRefreshTs) SECOND AS FLOAT) > 28800) THEN
    PROPAGATE TO TERMINAL 'out1';  -- route to cache-refresh Compute node
END IF;

-- Cache lookup using THE(SELECT ITEM ...)
SET outField = THE(SELECT ITEM S.TargetCode
                   FROM CacheData.Mappings.Data[] AS S
                   WHERE S.SourceCode = inputValue);

rule.template:
CREATE FUNCTION Main() RETURNS BOOLEAN
BEGIN
    IF someCondition THEN
        SET OutputLocalEnvironment.Destination.HTTP.RequestURL = urlA;
        PROPAGATE TO TERMINAL 'out';   -- route to path A
        RETURN FALSE;                  -- MUST follow: suppresses auto-propagate
    ELSE
        SET OutputLocalEnvironment.Destination.HTTP.RequestURL = urlB;
        PROPAGATE TO TERMINAL 'out1';  -- route to path B (custom terminal)
        RETURN FALSE;                  -- MUST follow
    END IF;
END;
